"""Lazy architecture: scoped aliases, typed event relations and batched reachability."""
import re
from data_layer_six.common import A,O,K,P,E,S,q,literals
from data_layer_eight.contracts import constants
from data_layer_eight.model import stages as model
from data_layer_eight.relations import clause


def candidate(source,policy):
    v=constants(source/'scripts/lint_lazy_architecture.py')
    vals=lambda *names:literals(set().union(*(v[name] for name in names)))
    prefixes=lambda name:q('^(?:'+'|'.join(map(re.escape,sorted(v[name])))+')')
    p=policy('lazy_architecture',['impl/**/*.py','api/**/*.py','data_layer/**/*.py','_internal/**/*.py','l[0-9][0-9][0-9][0-9]_*/**/*.py'])
    p['clauses'].append({'id':'entry','define':{'options':{'oracleAnalyzer':{'type':'boolean','default':False},'entryPoint':{'type':'string','default':'scan_files'}}}})
    stages=[*model(),
      S('imports',"""SELECT n.__path,n.id,n.__start,n.__end,n.module_name_source module,coalesce(x.alias_source,x.name_source,x.text) local,coalesce(x.name_source,x.text) name,n.kind,owner.fn FROM nodes n JOIN nodes x ON x.__path=n.__path AND x.parent=n.id AND x.kind IN ('dotted_name','aliased_import') AND x.id IS NOT n.module_name_kind||':'||n.module_name_start||':'||n.module_name_end JOIN ownership owner ON owner.__path=n.__path AND owner.id=n.id WHERE n.kind IN ('import_statement','import_from_statement')""",('__path','local')),
      S('analyzer_functions',"""SELECT f.*,replace(substr(f.__path,1,length(f.__path)-3),'/','.')||'.'||f.qualname symbol,
        rx_matches(f.__path,"""+prefixes('LAZY_SENSITIVE_PREFIXES')+") OR f.__path IN "+vals('LAZY_SENSITIVE_EXACT_FILES')+" OR rx_matches(f.__path,'^(?:l7200_versioned_transactions/_lint_|impl/common/l7300_revision_history/_lint_)') sensitive,\n        rx_matches(lower(f.__path||' '||f.qualname),'bootstrap|ddl') bootstrap,\n        rx_matches(lower(f.__path||' '||f.qualname),'reconcile|reconciliation|schema_ensure') OR f.__path IN ('l2000_connection/schema_transaction.py','l2000_connection/table_existence_authority.py','impl/common/l2200_sql_dialect/schema_ensure.py','impl/common/l2200_sql_dialect/sql_schema_services.py','impl/common/l2200_sql_dialect/sql_core_support_free_functions.py','impl/common/l2200_sql_dialect/sql_core_support_mixin.py') reconciliation\n        FROM declaration_contexts f JOIN nodes parent ON parent.__path=f.__path AND parent.id=f.parent LEFT JOIN nodes grand ON grand.__path=parent.__path AND grand.id=parent.parent LEFT JOIN nodes great ON great.__path=grand.__path AND great.id=grand.parent\n        WHERE f.kind='function_definition' AND NOT EXISTS(SELECT 1 FROM declaration_contexts a WHERE a.__path=f.__path AND a.kind='function_definition' AND a.region_start<f.region_start AND a.__end>=f.__end) AND (parent.kind='module' OR parent.kind='decorated_definition' AND grand.kind='module' OR parent.kind='block' AND grand.kind='class_definition' OR parent.kind='decorated_definition' AND grand.kind='block' AND great.kind='class_definition')",('__path','id'),('symbol',)),
      S('pruned_functions',"SELECT DISTINCT f.__path,f.id FROM declarations f JOIN decorator_names d ON d.__path=f.__path AND d.fn=f.id JOIN nodes expr ON expr.__path=d.__path AND expr.id=d.node WHERE f.kind='function_definition' AND expr.kind='attribute' AND d.name IN ('delete','get','patch','post','put')",('__path','id')),
      S('owned_nodes',"""WITH RECURSIVE owned(__path,fn,id) AS (
        SELECT __path,id,body_kind||':'||body_start||':'||body_end FROM analyzer_functions
        UNION ALL SELECT o.__path,o.fn,n.id FROM owned o JOIN nodes n ON n.__path=o.__path AND n.parent=o.id
        WHERE n.kind!='class_definition' AND NOT EXISTS(SELECT 1 FROM pruned_functions p WHERE p.__path=n.__path AND p.id=n.id))
        SELECT o.__path,o.fn,n.id,n.__start,n.__end,n.kind,n.text FROM owned o JOIN nodes n ON n.__path=o.__path AND n.id=o.id""",('__path','fn','id'),('__path','id'),('__path','__start','__end')),
      S('alias_regions',"SELECT b.__path,b.id,b.__start,b.__end FROM nodes b JOIN nodes parent ON parent.__path=b.__path AND parent.id=b.parent WHERE b.kind='block' AND parent.kind IN ('if_statement','elif_clause','else_clause','for_statement','while_statement','try_statement','except_clause','finally_clause','case_clause','function_definition')",('__path','__start','__end')),
      S('scoped_assignments',"SELECT a.*,coalesce((SELECT b.__start FROM alias_regions b WHERE b.__path=a.__path AND b.__start<=a.__start AND b.__end>=a.__end ORDER BY b.__start DESC LIMIT 1),0) scope_start,coalesce((SELECT b.__end FROM alias_regions b WHERE b.__path=a.__path AND b.__start<=a.__start AND b.__end>=a.__end ORDER BY b.__start DESC LIMIT 1),2147483647) scope_end FROM assignments a WHERE a.target_kind='identifier'",('__path','target_text','__end')),
      S('visible_bindings',"SELECT __path,fn,node,value FROM (SELECT r.__path,r.fn,r.id node,a.value,row_number() OVER(PARTITION BY r.__path,r.fn,r.id ORDER BY a.__start DESC) chosen FROM owned_nodes r JOIN analyzer_functions f ON f.__path=r.__path AND f.id=r.fn JOIN scoped_assignments a ON a.__path=r.__path AND a.target_text=r.text AND a.__end<r.__start AND a.__start>=f.body_start AND a.scope_start<=r.__start AND a.scope_end>=r.__end WHERE r.kind='identifier') WHERE chosen=1",('__path','fn','node')),
      S('terminal_values',"""WITH RECURSIVE terminal(__path,fn,root,node,depth,seen) AS (
        SELECT __path,fn,id,id,0,','||id||',' FROM owned_nodes WHERE kind IN ('identifier','attribute','call','parenthesized_expression')
        UNION ALL SELECT t.__path,t.fn,t.root,next.id,t.depth+1,t.seen||next.id||',' FROM terminal t JOIN nodes n ON n.__path=t.__path AND n.id=t.node LEFT JOIN visible_bindings binding ON binding.__path=n.__path AND binding.fn=t.fn AND binding.node=n.id JOIN nodes next ON next.__path=n.__path AND next.id=CASE WHEN n.kind='identifier' THEN binding.value WHEN n.kind='call' THEN n.function_kind||':'||n.function_start||':'||n.function_end WHEN n.kind='parenthesized_expression' THEN (SELECT child.id FROM nodes child WHERE child.__path=n.__path AND child.parent=n.id AND child.ordinal=0 LIMIT 1) END WHERE t.depth<64 AND instr(t.seen,','||next.id||',')=0)
        SELECT t.__path,t.fn,t.root,CASE WHEN n.kind='attribute' THEN n.attribute_source ELSE coalesce((SELECT i.module||'.'||i.name FROM imports i WHERE i.__path=n.__path AND i.local=n.text AND i.kind='import_from_statement' AND (i.fn IS NULL OR i.fn=t.fn) ORDER BY i.__start DESC LIMIT 1),n.text) END value FROM terminal t JOIN nodes n ON n.__path=t.__path AND n.id=t.node WHERE n.kind='attribute' OR n.kind='identifier' AND NOT EXISTS(SELECT 1 FROM visible_bindings b WHERE b.__path=n.__path AND b.fn=t.fn AND b.node=n.id)""",('__path','fn','root')),
      S('function_flags',"SELECT f.*,EXISTS(SELECT 1 FROM decorator_names d LEFT JOIN imports i ON i.__path=d.__path AND i.local=d.name WHERE d.__path=f.__path AND d.fn=f.id AND coalesce(i.name,d.name)='pure_lazy') pure,EXISTS(SELECT 1 FROM decorator_names d LEFT JOIN imports i ON i.__path=d.__path AND i.local=d.name WHERE d.__path=f.__path AND d.fn=f.id AND coalesce(i.name,d.name) IN ('legacy_sync','legacy_async','legacy_module_sync','legacy_module_async')) legacy FROM analyzer_functions f",('__path','id'),('symbol',)),
      S('owned_calls',"SELECT c.*,o.fn,coalesce(t.value,c.callee) resolved,rx_extract(coalesce(t.value,c.callee),'([^.]+)$',1) leaf FROM calls c JOIN owned_nodes o ON o.__path=c.__path AND o.id=c.id LEFT JOIN terminal_values t ON t.__path=c.__path AND t.fn=o.fn AND t.root=c.callee_id",('__path','fn'),('__path','id')),
      S('expression_tags',"""WITH RECURSIVE tag(__path,fn,node,kind) AS (
        SELECT o.__path,o.fn,o.id,'plan' FROM owned_nodes o JOIN terminal_values t ON t.__path=o.__path AND t.fn=o.fn AND t.root=o.id WHERE o.kind IN ('identifier','attribute') AND (t.value GLOB '*plan' OR o.text GLOB '*plan') OR o.kind='call' AND (t.value='plan' OR t.value GLOB '*_plan' OR t.value GLOB '_build_*')
        UNION SELECT o.__path,o.fn,o.id,'lazy' FROM owned_nodes o JOIN terminal_values t ON t.__path=o.__path AND t.fn=o.fn AND t.root=o.id WHERE o.kind='identifier' AND (instr(lower(t.value),'lazy')>0 OR t.value GLOB '*result' OR t.value GLOB '*Intent') OR o.kind IN ('attribute','call') AND (instr(t.value,'lazy')>0 OR t.value GLOB '*result')
        UNION SELECT __path,fn,id,'callable' FROM owned_nodes WHERE kind='lambda'
        UNION SELECT o.__path,o.fn,o.id,'internal' FROM owned_nodes o JOIN attributes a ON a.__path=o.__path AND a.id=o.id WHERE a.attr IN """+vals('LAZY_INTERNAL_ATTRS')+" UNION SELECT c.__path,c.fn,c.id,'internal' FROM owned_calls c LEFT JOIN arguments a ON a.__path=c.__path AND a.call=c.id AND a.position=1 LEFT JOIN strings s ON s.__path=a.__path AND s.__start=a.__start WHERE c.resolved IN ('_resolved_lazy_revision_value','_literalize_resolved_lazy_result') OR c.resolved IN ('__getattribute__','object.__getattribute__','getattr','builtins.getattr') AND s.value IN "+vals('LAZY_INTERNAL_ATTRS')+"\n UNION SELECT c.__path,c.fn,c.id,'dynamic' FROM owned_calls c LEFT JOIN arguments a ON a.__path=c.__path AND a.call=c.id AND a.position=CASE WHEN c.callee='get' THEN 0 ELSE 1 END LEFT JOIN strings s ON s.__path=a.__path AND s.__start=a.__start LEFT JOIN nodes receiver ON receiver.__path=c.__path AND receiver.id=c.receiver WHERE (c.resolved IN ('getattr','builtins.getattr','__getattribute__','object.__getattribute__') OR c.callee_kind='attribute' AND c.callee='get' AND a.id IS NOT NULL AND NOT (receiver.kind='identifier' AND rx_matches(receiver.text,'^[A-Z_]+$'))) AND a.id IS NOT NULL AND (s.value IS NULL OR rx_matches(lower(s.value),"+q('|'.join(sorted(v['SERVERPLAN_BEHAVIOR_KEY_PARTS'])))+"))\n UNION SELECT b.__path,b.fn,b.node,t.kind FROM tag t JOIN visible_bindings b ON b.__path=t.__path AND b.fn=t.fn AND b.value=t.node\n UNION SELECT parent.__path,t.fn,parent.id,t.kind FROM tag t JOIN nodes child ON child.__path=t.__path AND child.id=t.node JOIN nodes parent ON parent.__path=child.__path AND parent.id=child.parent WHERE t.kind IN ('callable','internal') AND (parent.kind IN ('tuple','list','set','dictionary','pair','argument_list','keyword_argument') OR parent.kind='attribute' AND parent.object_kind||':'||parent.object_start||':'||parent.object_end=child.id OR parent.kind='call' AND parent.arguments_kind||':'||parent.arguments_start||':'||parent.arguments_end=child.id)) SELECT * FROM tag",('__path','fn','node','kind')),
      S('classified_calls',"SELECT c.*,EXISTS(SELECT 1 FROM expression_tags t WHERE t.__path=c.__path AND t.fn=c.fn AND t.node=c.receiver AND t.kind='plan') plan_receiver,EXISTS(SELECT 1 FROM expression_tags t WHERE t.__path=c.__path AND t.fn=c.fn AND t.node=c.receiver AND t.kind='lazy') lazy_receiver FROM owned_calls c",('__path','fn'),('__path','id')),
      S('call_targets',"""SELECT c.__path,c.fn,c.id,c.__start,c.__end,
        CASE WHEN c.callee_kind='identifier' THEN coalesce((SELECT i.module||'.'||i.name FROM imports i WHERE i.__path=c.__path AND i.local=c.callee AND i.kind='import_from_statement' AND (i.fn IS NULL OR i.fn=c.fn) ORDER BY i.fn IS NOT NULL DESC,i.__start DESC LIMIT 1),replace(substr(c.__path,1,length(c.__path)-3),'/','.')||'.'||c.callee)
        WHEN c.callee_kind='attribute' AND receiver.kind='identifier' AND receiver.text IN ('self','cls') AND f.lexical_parent IS NOT NULL THEN (SELECT cls.symbol_prefix FROM (SELECT replace(substr(d.__path,1,length(d.__path)-3),'/','.')||'.'||d.qualname||'.' symbol_prefix FROM declaration_contexts d WHERE d.__path=f.__path AND d.id=f.lexical_parent) cls)||c.callee
        WHEN c.callee_kind='attribute' AND receiver.kind='identifier' THEN (SELECT i.name||'.'||c.callee FROM imports i WHERE i.__path=c.__path AND i.kind='import_statement' AND i.local=receiver.text ORDER BY i.__start DESC LIMIT 1) END target
        FROM owned_calls c JOIN function_flags f ON f.__path=c.__path AND f.id=c.fn LEFT JOIN nodes receiver ON receiver.__path=c.__path AND receiver.id=c.receiver""",('target',)),
      S('architecture_edges',"SELECT c.__path,c.fn,c.__start,c.id,t.__path target_path,t.id target FROM call_targets c JOIN function_flags t ON t.symbol=c.target WHERE t.__path!=c.__path OR t.id!=c.fn",('__path','fn')),
    ]
    events=[]
    def event(query):events.append(query)
    def calls(category,where,detail="c.leaf"):
        event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,"+q(category)+" category,"+detail+" detail FROM classified_calls c WHERE "+where)
    calls('plan',"c.leaf IN "+vals('PLAN_IO_NAMES'))
    calls('plan',"c.callee_kind='attribute' AND (c.callee IN ('execute','execute_async') AND c.plan_receiver OR c.callee IN "+vals('QUERY_BUILDER_RESULT_ATTRS')+" OR c.callee IN ('_execute_direct_internal','_execute_direct_internal_async') OR c.callee IN ('resolve','resolve_async') AND c.lazy_receiver)","CASE WHEN c.callee IN ('resolve','resolve_async') THEN 'lazy.'||c.callee WHEN c.plan_receiver THEN 'plan.'||c.callee ELSE c.callee END")
    calls('intent',"c.leaf IN "+vals('INTENT_HINTS')+" OR c.resolved GLOB '*Intent'")
    calls('grammar',"c.resolved GLOB 'grammar_*'")
    calls('native',"c.leaf IN "+vals('IMPERATIVE_NATIVE_ATTRS'))
    calls('private',"c.resolved IN ('getattr','builtins.getattr','vars','builtins.vars') AND EXISTS(SELECT 1 FROM arguments a LEFT JOIN strings s ON s.__path=a.__path AND s.__start=a.__start WHERE a.__path=c.__path AND a.call=c.id AND (c.resolved IN ('vars','builtins.vars') AND a.position=0 OR a.position=1 AND s.value='_conn'))")
    calls('internal',"c.resolved IN ('__getattribute__','object.__getattribute__','getattr','builtins.getattr') AND EXISTS(SELECT 1 FROM arguments a JOIN strings s ON s.__path=a.__path AND s.__start=a.__start WHERE a.__path=c.__path AND a.call=c.id AND a.position=1 AND s.value IN "+vals('LAZY_INTERNAL_ATTRS')+") AND EXISTS(SELECT 1 FROM arguments a JOIN expression_tags t ON t.__path=a.__path AND t.fn=c.fn AND t.node=a.id AND t.kind='lazy' WHERE a.__path=c.__path AND a.call=c.id AND a.position=0)")
    calls('state',"c.resolved IN ('setattr','builtins.setattr','__setattr__','object.__setattr__') AND EXISTS(SELECT 1 FROM arguments a JOIN strings s ON s.__path=a.__path AND s.__start=a.__start WHERE a.__path=c.__path AND a.call=c.id AND a.position=1 AND s.value IN "+vals('PLANNER_STATE_ATTRS')+") AND EXISTS(SELECT 1 FROM arguments a JOIN expression_tags t ON t.__path=a.__path AND t.fn=c.fn AND t.node=a.id AND t.kind='internal' WHERE a.__path=c.__path AND a.call=c.id AND a.position=2)")
    calls('forbidden_pure',"c.leaf IN "+vals('FORBIDDEN_PURE_LAZY_CALLEE_NAMES'))
    calls('reconciliation',"c.leaf IN "+vals('RECONCILIATION_SCHEMA_DISCOVERY_NAMES','RECONCILIATION_DIRECT_DDL_NAMES','RECONCILIATION_CALLBACK_TRAMPOLINE_NAMES')+" AND NOT (c.leaf='flush_schema_plan' AND EXISTS(SELECT 1 FROM function_flags f WHERE f.__path=c.__path AND f.id=c.fn AND (f.name IN "+vals('SCHEMA_RECONCILIATION_ALLOWED_FLUSH_WRAPPER_NAMES')+" OR f.qualname IN "+vals('SCHEMA_RECONCILIATION_ALLOWED_FLUSH_WRAPPERS')+")))")
    calls('bootstrap',"c.callee_kind='attribute' AND c.callee IN "+vals('BOOTSTRAP_LAZY_MUTATOR_ATTRS')+" AND EXISTS(SELECT 1 FROM expression_roots root WHERE root.__path=c.__path AND root.expression=c.receiver AND root.name IN ('self','cls'))")
    calls('absence',"c.leaf='_record_table_exists_result' AND EXISTS(SELECT 1 FROM arguments a WHERE a.__path=c.__path AND a.call=c.id AND a.position=1 AND a.kind='false')")
    calls('dynamic',"EXISTS(SELECT 1 FROM function_flags f WHERE f.__path=c.__path AND f.id=c.fn AND f.name GLOB 'materialize_*') AND (c.resolved IN ('callable','builtins.callable') AND EXISTS(SELECT 1 FROM arguments a JOIN expression_tags t ON t.__path=a.__path AND t.fn=c.fn AND t.node=a.id AND t.kind='dynamic' WHERE a.__path=c.__path AND a.call=c.id AND a.position=0) OR c.callee_kind='identifier' AND EXISTS(SELECT 1 FROM expression_tags t WHERE t.__path=c.__path AND t.fn=c.fn AND t.node=c.callee_id AND t.kind='dynamic'))")
    calls('payload',"EXISTS(SELECT 1 FROM keywords k JOIN expression_tags t ON t.__path=k.__path AND t.fn=c.fn AND t.node=k.value AND t.kind='callable' WHERE k.__path=c.__path AND k.call=c.id AND (k.name='closed_post_op' OR NOT EXISTS(SELECT 1 FROM keywords closed WHERE closed.__path=c.__path AND closed.call=c.id AND closed.name='closed_post_op') AND (c.resolved IN ('literal_post_op','l2070_batching.post_op.literal_post_op','runtime_builder_post_op','l2070_batching.post_op.runtime_builder_post_op') OR c.leaf='RuntimeBuilderSpec' AND k.name='literal_kwargs' OR c.leaf='ResultMaterializationSpec' AND k.name IN ('literal_payload','default_value')))) OR c.resolved IN ('literal_post_op','l2070_batching.post_op.literal_post_op') AND NOT EXISTS(SELECT 1 FROM keywords closed WHERE closed.__path=c.__path AND closed.call=c.id AND closed.name='closed_post_op') AND EXISTS(SELECT 1 FROM arguments a JOIN expression_tags t ON t.__path=a.__path AND t.fn=c.fn AND t.node=a.id AND t.kind='callable' WHERE a.__path=c.__path AND a.call=c.id AND a.position=0)")
    event("SELECT s.__path,o.fn,s.__start,s.__start,s.__end,'dolt',s.value FROM strings s JOIN owned_nodes o ON o.__path=s.__path AND o.__start=s.__start AND o.__end=s.__end WHERE rx_matches(lower(s.value),'dolt_|dolt log|dolt branches')")
    event("SELECT a.__path,o.fn,a.id,a.__start,a.__end,'bootstrap',a.target_text FROM assignments a JOIN owned_nodes o ON o.__path=a.__path AND o.id=a.id JOIN nodes target ON target.__path=a.__path AND target.id=a.target JOIN expression_roots root ON root.__path=target.__path AND root.expression=target.id WHERE target.kind IN ('attribute','subscript') AND root.name IN ('self','cls')")
    event("SELECT r.__path,o.fn,r.id,r.__start,r.__end,'of_return','LazyResult.of' FROM returns r JOIN owned_nodes o ON o.__path=r.__path AND o.id=r.id JOIN calls c ON c.__path=r.__path AND c.id=r.value WHERE c.callee_kind='attribute' AND c.callee='of' AND rx_matches(c.full_callee,'(?:^|\\.)LazyResult\\.of$')")
    event("SELECT a.__path,o.fn,a.id,a.__start,a.__end,'absence','empty snapshot' FROM assignments a JOIN owned_nodes o ON o.__path=a.__path AND o.id=a.id JOIN calls c ON c.__path=a.__path AND c.id=a.value WHERE a.target_kind='identifier' AND rx_matches(a.target_text,'snapshot|existing') AND c.callee_kind='identifier' AND c.callee IN ('set','frozenset') AND NOT EXISTS(SELECT 1 FROM nodes args WHERE args.__path=c.__path AND args.parent=c.arguments_kind||':'||c.arguments_start||':'||c.arguments_end AND args.kind!='comment')")
    event("SELECT r.__path,o.fn,r.id,r.__start,r.__end,'absence','false return' FROM returns r JOIN owned_nodes o ON o.__path=r.__path AND o.id=r.id JOIN calls c ON c.__path=r.__path AND c.id=r.value JOIN arguments a ON a.__path=c.__path AND a.call=c.id AND a.position=0 JOIN function_flags f ON f.__path=o.__path AND f.id=o.fn WHERE a.kind='false' AND c.callee_kind='attribute' AND c.callee='of' AND rx_matches(c.full_callee,'(?:^|\\.)LazyResult\\.of$') AND f.name!='table_exists_lazy' AND instr(lower(f.qualname),'_should_skip_')=0 AND rx_matches(lower(f.qualname),'schema_fact|exists|has_|table|column|index|trigger')")
    event("SELECT f.__path,f.id,f.id,f.__start,f.__end,'context',f.name FROM function_flags f JOIN declaration_contexts cls ON cls.__path=f.__path AND cls.id=f.lexical_parent JOIN nodes supers ON supers.__path=cls.__path AND supers.parent=cls.id AND supers.kind='argument_list' WHERE f.name IN ('execute_sync','execute_async') AND rx_matches(supers.text,'ExecutionContext')")
    stages.extend([
      S('function_events',' UNION ALL '.join(events),('__path','fn','category')),
      S('reachable',"WITH RECURSIVE reach(__path,root,path,node,first) AS (SELECT __path,id,__path,id,NULL FROM function_flags UNION SELECT r.__path,r.root,e.target_path,e.target,coalesce(r.first,e.__start) FROM reach r JOIN architecture_edges e ON e.__path=r.path AND e.fn=r.node WHERE r.path=r.__path) SELECT * FROM reach",('__path','root'),('path','node')),
      S('rollups',"SELECT r.__path,r.root,e.category,min(CASE WHEN r.first IS NULL THEN -1000000000+e.__start ELSE r.first END) location FROM reachable r JOIN function_events e ON e.__path=r.path AND e.fn=r.node WHERE e.category IN ('plan','intent','grammar','native','dolt') GROUP BY r.__path,r.root,e.category",('__path','root','category')),
      S('intrinsic',"SELECT f.__path,f.id FROM function_flags f WHERE f.legacy OR rx_matches(f.text,'^async\\b') AND NOT f.pure OR f.name GLOB '*_async' OR EXISTS(SELECT 1 FROM function_events e WHERE e.__path=f.__path AND e.fn=f.id AND (e.category IN ('plan','native') OR f.sensitive AND e.category IN ('context','internal','state','private')))",('__path','id')),
      S('transitive_matches',"SELECT r.__path,r.root,min(CASE WHEN r.first IS NULL THEN -1000000000+coalesce((SELECT min(e.__start) FROM function_events e WHERE e.__path=f.__path AND e.fn=f.id),f.__start) ELSE r.first END) eager FROM reachable r JOIN function_flags f ON f.__path=r.path AND f.id=r.node JOIN intrinsic i ON i.__path=f.__path AND i.id=f.id GROUP BY r.__path,r.root",('__path','root')),
      S('non_lazy_matches',"SELECT r.__path,r.root,min(r.first) location FROM reachable r JOIN function_flags f ON f.__path=r.path AND f.id=r.node WHERE r.first IS NOT NULL AND NOT f.pure AND f.name NOT GLOB '*_lazy' AND f.symbol NOT IN "+vals('SANCTIONED_PURE_HELPER_SYMBOLS')+" GROUP BY r.__path,r.root",('__path','root')),
      S('legacy_matches',"SELECT r.__path,r.root,min(r.first) location FROM reachable r JOIN function_flags f ON f.__path=r.path AND f.id=r.node WHERE r.first IS NOT NULL AND f.legacy GROUP BY r.__path,r.root",('__path','root')),
    ])
    rows=[]
    def finding(code,query):rows.append(query.replace('{code}',q(code)))
    def local(code,category,where='1',first=False):
        finding(code,"SELECT f.__path path,e.__start start_byte,e.__end end_byte,{code} issue,f.id||':"+category+":'||e.id identity FROM function_flags f JOIN function_events e ON e.__path=f.__path AND e.fn=f.id WHERE e.category="+q(category)+" AND "+where+(" AND e.__start=(SELECT min(other.__start) FROM function_events other WHERE other.__path=f.__path AND other.fn=f.id AND other.category=e.category)" if first else ''))
    def rolled(code,category,where):
        finding(code,"SELECT f.__path path,CASE WHEN r.location<0 THEN r.location+1000000000 ELSE r.location END start_byte,CASE WHEN r.location<0 THEN r.location+1000000000 ELSE r.location END end_byte,{code} issue,f.id||':"+code+"' identity FROM function_flags f JOIN rollups r ON r.__path=f.__path AND r.root=f.id AND r.category="+q(category)+" WHERE "+where)
    rolled('LA-001','plan','f.pure')
    rolled('LA-002','plan',"EXISTS(SELECT 1 FROM rollups intent WHERE intent.__path=f.__path AND intent.root=f.id AND intent.category='intent')")
    rolled('LA-003','plan',"f.name NOT GLOB '_*' AND f.name NOT GLOB '*_lazy' AND NOT f.pure AND (rx_matches(f.__path,"+prefixes('FEATURE_PUBLIC_PREFIXES')+") OR f.__path='impl/common/l5200_sql_query/_insert_from_query.py') AND NOT EXISTS(SELECT 1 FROM rollups intent WHERE intent.__path=f.__path AND intent.root=f.id AND intent.category='intent')")
    rolled('LA-004','native',"NOT rx_matches(f.__path,'migration') AND EXISTS(SELECT 1 FROM rollups plan WHERE plan.__path=f.__path AND plan.root=f.id AND plan.category='plan')")
    finding('LA-005',"SELECT f.__path path,CASE WHEN min(r.location)<0 THEN min(r.location)+1000000000 ELSE min(r.location) END start_byte,CASE WHEN min(r.location)<0 THEN min(r.location)+1000000000 ELSE min(r.location) END end_byte,{code} issue,f.id identity FROM function_flags f JOIN rollups r ON r.__path=f.__path AND r.root=f.id AND r.category IN ('dolt','native') WHERE rx_matches(f.__path,"+prefixes('NATIVE_ORCHESTRATION_PATHS')+") GROUP BY f.__path,f.id")
    local('LA-006','plan',"EXISTS(SELECT 1 FROM classified_calls c WHERE c.__path=e.__path AND c.id=e.id AND EXISTS(SELECT 1 FROM attributes attr WHERE attr.__path=c.__path AND attr.attr='_conn' AND (EXISTS(SELECT 1 FROM arguments a WHERE a.__path=c.__path AND a.call=c.id AND a.position=0 AND attr.__start>=a.__start AND attr.__end<=a.__end) OR EXISTS(SELECT 1 FROM keywords k WHERE k.__path=c.__path AND k.call=c.id AND k.name IN ('owner','txn','tx','conn','connection') AND attr.__start>=k.__start AND attr.__end<=k.__end))))")
    rolled('LA-007','plan',"f.name GLOB 'prepare_*'")
    finding('LA-008',"SELECT f.__path path,f.__start start_byte,f.__end end_byte,{code} issue,f.id identity FROM function_flags f WHERE rx_matches(f.__path,"+prefixes('TRANSACTION_PREFIXES')+") AND EXISTS(SELECT 1 FROM rollups grammar WHERE grammar.__path=f.__path AND grammar.root=f.id AND grammar.category='grammar') AND EXISTS(SELECT 1 FROM function_flags async_fn JOIN reachable r ON r.__path=async_fn.__path AND r.root=async_fn.id JOIN function_events e ON e.__path=r.path AND e.fn=r.node WHERE async_fn.__path=f.__path AND async_fn.name=f.name||'_async' AND e.category IN ('plan','grammar') AND e.detail GLOB '*_async')")
    for category in ('context','internal','state','private'):local('LA-009',category,'f.sensitive',True)
    finding('LA-009',"SELECT f.__path path,CASE WHEN t.eager<0 THEN t.eager+1000000000 ELSE t.eager END start_byte,CASE WHEN t.eager<0 THEN t.eager+1000000000 ELSE t.eager END end_byte,{code} issue,f.id||':eager' identity FROM function_flags f JOIN transitive_matches t ON t.__path=f.__path AND t.root=f.id WHERE f.pure AND NOT EXISTS(SELECT 1 FROM legacy_matches l WHERE l.__path=f.__path AND l.root=f.id)")
    finding('LA-010',"SELECT f.__path path,f.__start start_byte,f.__end end_byte,{code} issue,f.id identity FROM function_flags f WHERE instr(lower(f.name),'lazy')>0 AND rx_matches(lower(f.name),'async|sync')")
    rolled('LA-011','plan',"f.__path GLOB 'impl/common/l2070_server_plan/*' AND f.name IN ('lower','compile','preprocess','pre_op','post_op')")
    local('LA-011','forbidden_pure','0')
    local('LA-012','plan',"NOT f.legacy AND e.detail IN ('lazy.resolve','lazy.resolve_async')",True)
    local('LA-013','forbidden_pure','f.pure')
    finding('LA-013',"SELECT f.__path path,l.location start_byte,l.location end_byte,{code} issue,f.id||':legacy' identity FROM function_flags f JOIN legacy_matches l ON l.__path=f.__path AND l.root=f.id WHERE f.pure")
    finding('LA-013',"SELECT f.__path path,n.location start_byte,n.location end_byte,{code} issue,f.id||':nonlazy' identity FROM function_flags f JOIN non_lazy_matches n ON n.__path=f.__path AND n.root=f.id WHERE (f.pure OR f.name GLOB '*_lazy') AND NOT (f.pure AND EXISTS(SELECT 1 FROM legacy_matches l WHERE l.__path=f.__path AND l.root=f.id))")
    for category in ('payload','dynamic'):local('LA-014',category,"rx_matches(f.__path,"+prefixes('SERVERPLAN_SERVICE_PREFIXES')+") OR f.__path IN "+vals('SERVERPLAN_SERVICE_EXACT_FILES'))
    local('LA-015','of_return','f.bootstrap')
    local('LA-016','bootstrap','f.bootstrap AND f.pure')
    for category in ('reconciliation','absence'):local('LA-017',category,'f.reconciliation')
    local('LA-017','plan',"rx_matches(lower(f.__path||' '||f.qualname),'reconcile|reconciliation|schema_ensure') AND (f.__path GLOB 'impl/common/l2200_sql_dialect/*' OR f.__path='l2000_connection/schema_transaction.py') AND e.detail IN ('lazy.resolve','lazy.resolve_async')")
    finding('LA-017',"SELECT f.__path path,f.__start start_byte,f.__end end_byte,{code} issue,f.id identity FROM function_flags f WHERE f.reconciliation AND f.__path||'::'||f.qualname IN "+vals('SCHEMA_RECONCILIATION_FORBIDDEN_SURFACES'))
    # Class side-queue declarations are pseudo-functions in the original fact model.
    finding('LA-016',"SELECT a.__path path,a.__start start_byte,a.__end end_byte,{code} issue,a.id||':sidequeue' identity FROM assignments a JOIN nodes expression ON expression.__path=a.__path AND expression.id=a.parent JOIN classes cls ON cls.__path=expression.__path AND expression.parent=cls.body_kind||':'||cls.body_start||':'||cls.body_end WHERE a.target_kind='identifier' AND a.target_text IN "+vals('BOOTSTRAP_LAZY_FORBIDDEN_SIDE_QUEUE_ATTRS')+" AND rx_matches(lower(a.__path||' '||cls.name||'.'||a.target_text),'bootstrap|ddl')")
    finding('LA-013',"SELECT c.__path path,c.__start start_byte,c.__end end_byte,{code} issue,c.id||':defer' identity FROM calls c WHERE c.callee='defer_lazy_result' AND c.callee_kind IN ('identifier','attribute') UNION ALL SELECT i.__path,i.__start,i.__end,{code},i.id||':'||i.local FROM imports i WHERE i.module='l2055_lazy_result.transform' AND i.name='defer_lazy_result'")
    finding('LA-009',"SELECT c.__path path,c.__start start_byte,c.__end end_byte,{code} issue,c.id||':compat' identity FROM calls c WHERE c.callee IN "+vals('FORBIDDEN_LAZY_COMPAT_CALLS','FORBIDDEN_LAZY_COMPAT_HELPERS')+" AND (rx_matches(c.__path,"+prefixes('LAZY_SENSITIVE_PREFIXES')+") OR c.__path IN "+vals('LAZY_SENSITIVE_EXACT_FILES')+" OR rx_matches(c.__path,'^(?:l7200_versioned_transactions/_lint_|impl/common/l7300_revision_history/_lint_)'))")
    # Keep each diagnostic statement bounded; all packets consume these shared facts.
    for index in range(0,len(rows),6):stages.append(S('diagnostics_'+str(index//6),' UNION ALL '.join(rows[index:index+6])))
